import os
import subprocess
import flask
from flask import Flask, request, jsonify
import hashlib
import hmac
import time

app = Flask(__name__)

# Configuration
UPLOAD_DIR = "/var/data/reports"
ALLOWED_EXTENSIONS = {'.pdf', '.csv', '.xlsx'}
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def verify_request_signature(req):
    """Verify HMAC signature on incoming requests"""
    sig = req.headers.get('X-Signature')
    if not sig:
        return False
    body = req.get_data()
    expected = hmac.new(SECRET_KEY.encode(), body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

def sanitize_filename(filename):
    """Remove directory traversal attempts - basic sanitization"""
    # Strip leading/trailing whitespace and null bytes
    filename = filename.strip().replace('\x00', '')
    # Remove leading dots and slashes
    while filename.startswith(('.', '/')):
        filename = filename[1:]
    return filename

def get_file_extension(filename):
    """Extract extension for validation"""
    parts = filename.rsplit('.', 1)
    if len(parts) == 2:
        return '.' + parts[1].lower()
    return ''

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report by invoking system reporting tool"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    report_type = data.get('type', 'summary')
    date_range = data.get('date_range', 'last_7d')
    output_format = data.get('format', 'pdf')
    template_name = data.get('template', 'default')

    # Validate report type
    if report_type not in ('summary', 'detailed', 'audit', 'compliance'):
        return jsonify({'error': 'Invalid report type'}), 400

    # Validate output format
    if output_format not in ('pdf', 'csv', 'xlsx'):
        return jsonify({'error': 'Invalid format'}), 400

    # Validate date range format
    if not date_range.replace('_', '').replace('last', '').replace('d', '').replace('m', '').isalnum():
        return jsonify({'error': 'Invalid date range'}), 400

    # Build command for report generation tool
    output_file = f"/var/data/reports/{report_type}_{int(time.time())}.{output_format}"

    # Template name is used to select report layout
    cmd = f"/usr/local/bin/report-gen --type {report_type} --range {date_range} --template {template_name} --output {output_file}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode == 0:
            return jsonify({
                'status': 'success',
                'file': output_file,
                'size': os.path.getsize(output_file) if os.path.exists(output_file) else 0
            })
        else:
            return jsonify({
                'status': 'error',
                'detail': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v2/reports/list', methods=['GET'])
def list_reports():
    """List available reports"""
    try:
        files = os.listdir(UPLOAD_DIR)
        reports = [f for f in files if get_file_extension(f) in ALLOWED_EXTENSIONS]
        return jsonify({'reports': reports})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
